(()=>{const result={},ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');document.body.append(svg);for(const family of ['serif','"Segoe UI Emoji"','serif, "Segoe UI Emoji"','"Arial", serif'])for(const text of ['A','😀','A😀B','😀😀','👩‍💻','❤️','é','A👩‍💻B','☺️','☺︎','👍🏽']){const n=document.createElementNS(ns,'text');n.style.fontFamily=family;n.style.fontSize='16px';n.textContent=text;svg.append(n);const b=n.getBBox();result[family+'|'+text]={length:n.getComputedTextLength(),box:[b.x,b.y,b.width,b.height]};n.remove()}svg.remove();return result})()